CREATE  /* DEFINER=`laravel_mediaprint`@`%` */ PROCEDURE `sp_recalc_ddt`(IN `p_id` INT)
BEGIN
  DECLARE v_pezzi BIGINT DEFAULT 0;
  DECLARE v_peso  DECIMAL(18,3) DEFAULT 0.000;

  SELECT
    COALESCE(SUM(quantita),0),
    COALESCE(SUM(peso_totale_kg),0)
  INTO v_pezzi, v_peso
  FROM tb_ddt_righe
  WHERE id_ddt = p_id;

  UPDATE tb_ddt
  SET totale_pezzi = v_pezzi,
      totale_peso_kg = v_peso
  WHERE id_ddt = p_id;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
